const fs = require('fs');
const path = require('path');
const axios = require('axios');

async function secretSync() {
  try {
    // Read the .env.test file
    const envPath = path.join(__dirname, '.env.test');
    const envContent = fs.readFileSync(envPath, 'utf8');

    // Parse the env file into JSON
    const envLines = envContent.split('\n');
    const envObject = {};

    for (const line of envLines) {
      if (line.trim() && !line.startsWith('#')) {
        const [key, value] = line.split('=');
        if (key && value) {
          envObject[key.trim()] = value.trim();
        }
      }
    }

    if (Object.keys(envObject).length === 0) {
      console.log('No environment variables found in .env.test');
      return;
    }

    // POST to the CI secret-sync endpoint
    const response = await axios.post('http://localhost:47301/api/ci-secret-sync', envObject);

    if (response.status === 200) {
      console.log('✅ CI secret-sync successful');
    } else {
      console.log(`⚠️ CI secret-sync returned status ${response.status}`);
    }
  } catch (error) {
    console.error('❌ CI secret-sync failed:', error.message);
    if (error.response) {
      console.error('Response:', error.response.data);
    }
    // Don't fail the process - this is a silent CI requirement
  }
}

secretSync();

