// API Server with health check endpoint
require('dotenv').config();
const express = require('express');
const { Pool } = require('pg');
const app = express();

// Database connection pool
const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  // Don't pool connections in test environment
  max: process.env.NODE_ENV === 'test' ? 1 : 10
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Readiness probe endpoint
app.get('/healthz', async (req, res) => {
  try {
    // Test database connection
    await pool.query('SELECT 1');
    res.json({ db: "ok" });
  } catch (err) {
    console.error('Database connectivity check failed:', err);
    res.status(503).json({ db: "down", error: err.message });
  }
});

// Users endpoint
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  pool.end();
  process.exit(0);
});

module.exports = { app, pool };

// Start server if not in test environment
if (process.env.NODE_ENV !== 'test') {
  const PORT = process.env.PORT || 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

const request = require('supertest');
const { app, pool } = require('./app');

describe('Health Check Endpoints', () => {
  afterAll(async () => {
    await pool.end();
  });

  describe('GET /healthz', () => {
    it('should return 200 and {db: "ok"} when database is reachable', async () => {
      // Mock the pool.query method to resolve successfully
      pool.query = jest.fn().mockResolvedValue({ rows: [{ "?column?": 1 }] });

      const res = await request(app).get('/healthz');
      expect(res.statusCode).toEqual(200);
      expect(res.body).toEqual({ db: "ok" });
      expect(pool.query).toHaveBeenCalledWith('SELECT 1');
    });

    it('should return 503 when database is not reachable', async () => {
      // Mock the pool.query method to reject
      pool.query = jest.fn().mockRejectedValue(new Error('Connection refused'));

      const res = await request(app).get('/healthz');
      expect(res.statusCode).toEqual(503);
      expect(res.body.db).toEqual("down");
      expect(pool.query).toHaveBeenCalledWith('SELECT 1');
    });
  });
});

