const express = require('express');
const app = express();

// Try to connect to PostgreSQL
function checkPostgresHealth() {
  return new Promise((resolve) => {
    const { Pool } = require('pg');
    const pool = new Pool({
      connectionString: process.env.DATABASE_URL,
      // Set a short timeout for health checks
      connectionTimeoutMillis: 2000,
      idleTimeoutMillis: 1000
    });

    // Try to get a client from the pool
    pool.query('SELECT 1 as health_check')
      .then(() => {
        pool.end(); // Close the pool
        resolve(true);
      })
      .catch((err) => {
        console.error('Postgres health check failed:', err.message);
        pool.end(); // Close the pool
        resolve(false);
      });
  });
}

// Existing health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// New healthz endpoint for k8s readiness probe
app.get('/healthz', async (req, res) => {
  try {
    const dbOk = await checkPostgresHealth();
    if (dbOk) {
      return res.status(200).json({"db":"ok"});
    }
    return res.status(503).json({"db":"unavailable"});
  } catch (err) {
    console.error('Health check error:', err);
    return res.status(503).json({"db":"error"});
  }
});

