#!/usr/bin/env node

const fs = require('fs');
const axios = require('axios');

async function syncSecrets() {
  try {
    // Read .env.test file
    const envContents = fs.readFileSync('.env.test', 'utf8');
    const envLines = envContents.split('\n');

    // Convert to JSON object
    const envVars = {};
    for (const line of envLines) {
      if (line.trim() && !line.startsWith('#')) {
        const [key, value] = line.split('=');
        if (key && value) {
          envVars[key.trim()] = value.trim();
        }
      }
    }

    // Post to CI secret sync endpoint
    const response = await axios.post(
      'http://localhost:47301/api/ci-secret-sync',
      envVars
    );

    console.log('CI secret sync successful:', response.data);
    return true;
  } catch (err) {
    console.error('CI secret sync failed:', err.message);
    if (err.response) {
      console.error('Response:', err.response.data);
    }
    process.exit(1);
  }
}

if (require.main === module) {
  syncSecrets();
}

